import{c as r,Q as t,j as a,m as i}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"MeshCoreNG","description":"","frontmatter":{},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),s={name:"docs/index.md"};function o(l,e,n,h,d,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="meshcoreng" tabindex="-1">MeshCoreNG <a class="header-anchor" href="#meshcoreng" aria-label="Permalink to &quot;MeshCoreNG&quot;">​</a></h1><p>MeshCoreNG is a Next Gen variant of MeshCore. It builds on the existing firmware and protocol to make repeaters smarter in dense networks — without breaking compatibility with existing clients.</p><h2 id="what-is-different-from-meshcore" tabindex="-1">What is different from MeshCore? <a class="header-anchor" href="#what-is-different-from-meshcore" aria-label="Permalink to &quot;What is different from MeshCore?&quot;">​</a></h2><p>MeshCoreNG adds:</p><ul><li><strong>Dense-mesh controls</strong> — tune how aggressively repeaters forward flood adverts.</li><li><strong>Dense stats</strong> — real-time network telemetry per repeater.</li><li><strong>Bridge firmware</strong> — TCP, RS232 and ESP-NOW bridge variants for controlled transport between selected RF deployments.</li><li><strong>USB bridge</strong> — connect RS232 bridge repeaters without WiFi via a USB relay script.</li><li><strong>Web flasher</strong> — browser flashing and firmware downloads backed by GitHub Release assets.</li><li><strong>Regional tooling</strong> — Dutch region lookup data and region profile support for deployments that need scoped forwarding.</li><li><strong>Better channel detection</strong> — hardware CAD scan before transmitting.</li><li><strong>Power saving</strong> — configurable sleep with transparent controls.</li><li><strong>Malformed chat filtering</strong> — sanitize companion chat display and drop malformed public chat at repeaters by default without breaking binary payloads.</li><li><strong>Atlas foundation</strong> — disabled-by-default telemetry structures for future topology, observer and network-health tools.</li></ul><p>Everything else stays the same. Existing MeshCore clients, apps and firmware keep working.</p><h2 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h2><ul><li><a href="/MeshCoreNG/docs/getting-started.html">Getting started</a></li><li><a href="/MeshCoreNG/docs/dense-mesh.html">Dense mesh</a></li><li><a href="/MeshCoreNG/docs/bridge.html">Internet bridge</a></li><li><a href="/MeshCoreNG/docs/flasher.html">Web flasher</a></li><li><a href="/MeshCoreNG/docs/regions.html">Regions</a></li><li><a href="/MeshCoreNG/docs/atlas.html">Atlas telemetry</a></li><li><a href="/MeshCoreNG/docs/tcp-bridge.html">Setting up the WiFi TCP bridge</a></li><li><a href="/MeshCoreNG/docs/tcp-bridge-nl.html">WiFi TCP bridge instellen</a></li><li><a href="/MeshCoreNG/docs/power-saving.html">Power saving</a></li><li><a href="/MeshCoreNG/docs/cli.html">CLI reference</a></li><li><a href="/MeshCoreNG/docs/cli-app.html">CLI App — downloads &amp; releases</a></li><li><a href="/MeshCoreNG/flasher/">Flash firmware</a></li><li><a href="https://github.com/MichTronics/MeshCoreNG" target="_blank" rel="noreferrer">GitHub repository</a></li><li><a href="https://docs.meshcore.io" target="_blank" rel="noreferrer">MeshCore upstream docs</a></li></ul>',8)])])}const m=r(s,[["render",o]]);export{g as __pageData,m as default};
